function filtered(){const q=norm(query.trim());return docs().filter(d=>(!category||String(d.kategori||'Diğer')===category)&&(!q||norm([d.ad,d.baslik,d.dosyaAdi,d.kategori,d.olusturanAdi,d.aciklama].filter(Boolean).join(' ')).includes(q)))}
async function prepareLocal(){if(!SyncEngine||!COL?.dokumanlar)return;const types=[];if(admin()){SyncEngine.register('dokumanlar',COL.dokumanlar);types.push('dokumanlar')}else{SyncEngine.register('dokumanlarAcik',COL.dokumanlar,{query:q=>q.where('gorunurluk','==','herkes')});types.push('dokumanlarAcik');const u=uid();if(u){SyncEngine.register('dokumanlarBenim',COL.dokumanlar,{query:q=>q.where('olusturanUid','==',u)});types.push('dokumanlarBenim')}}if(types.length){await SyncEngine.localHydrate(types);SyncEngine.schedule(120)}}
function shell(){return `<section class="ka-stack ka-documents-page" data-documents-module><div class="ka-row ka-row--between"><div><h2>Dokümanlar ve Raporlar</h2><p class="ka-muted">Erişebildiğiniz dokümanlar cihazdan açılır.</p></div><span id="documentsCount" class="ka-badge"></span></div><div class="ka-row"><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-document-form="teblig" data-ka-permission="documents.view" data-ka-min-level="preview">Tebliğ‑Tebellüğ Formu</button></div><div id="documentsToolbar" class="ka-stack ka-documents-toolbar"></div><label class="ka-field"><span class="ka-field__label">Ara</span><input id="documentsSearch" type="search" placeholder="Doküman, kategori veya oluşturan kişi ara…"></label><div id="documentsContent" class="ka-stack"></div></section>`}
