function ensureViewer(){if(window.DokumanOkuyucu)return Promise.resolve(window.DokumanOkuyucu);if(viewerPromise)return viewerPromise;viewerPromise=new Promise((resolve,reject)=>{const mevcut=[...document.scripts].find(s=>String(s.getAttribute('src')||'').split('?')[0].endsWith('js/modules/document-viewer.js'));if(mevcut){mevcut.addEventListener('load',()=>resolve(window.DokumanOkuyucu),{once:true});mevcut.addEventListener('error',()=>reject(new Error('Belge görüntüleyici yüklenemedi.')),{once:true});return;}const s=document.createElement('script');s.src='js/modules/document-viewer.js';s.async=true;s.dataset.korukCapability='document-viewer';s.onload=()=>window.DokumanOkuyucu?resolve(window.DokumanOkuyucu):reject(new Error('Belge görüntüleyici hazır değil.'));s.onerror=()=>reject(new Error('Belge görüntüleyici yüklenemedi.'));document.head.appendChild(s)}).catch(e=>{viewerPromise=null;throw e});return viewerPromise;}
function resolveDoc(v){return typeof v==='string'?docs().find(x=>x.id===v):v}
async function openDocument(v){const d=resolveDoc(v),url=safeUrl(urlOf(d));if(!d||!url)return window.toast?.('Bu dokümanın dosyası bulunamadı.');try{if(PermissionService?.can?.('documents.view','preview')===false)throw new Error('yetkisiz');const viewer=await ensureViewer(),name=d.dosyaAdi||d.ad||d.baslik||'Belge';if(viewer&&(viewer.googleDocsMu?.(url)||viewer.destekliMi?.(name)||viewer.destekliMi?.(url))){await viewer.ac(url,name);return}window.open(url,'_blank','noopener')}catch(e){console.warn('[Documents/viewer]',e);if(e?.message!=='yetkisiz')window.open(url,'_blank','noopener')}}
async function downloadDocument(id){const d=resolveDoc(id),url=safeUrl(urlOf(d));if(!d||!url)return;try{const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error('Dosya alınamadı ('+r.status+')');const blob=await r.blob(),name=d.dosyaAdi||d.ad||'dosya';if(typeof window.uygulamaDosyaKaydet==='function'){const fr=new FileReader(),b64=await new Promise((ok,no)=>{fr.onloadend=()=>ok(String(fr.result).split(',')[1]);fr.onerror=no;fr.readAsDataURL(blob)});await window.uygulamaDosyaKaydet(b64,name,blob.type||'application/octet-stream',false);return}const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000)}catch(e){console.warn('[Documents/download]',e);window.open(url,'_blank','noopener')}}
