function move(list,i,d){const j=i+d;if(j<0||j>=list.length)return;[list[i],list[j]]=[list[j],list[i]];}
function resultControls(){if(!resultBlob)return'';return `<article class="ka-card"><div class="ka-card__body ka-stack"><div class="ka-row ka-row--between"><strong>PDF hazır</strong><span class="ka-badge">${bytes(resultBlob.size)}</span></div><div class="ka-row ka-wrap"><button class="ka-btn ka-btn--secondary" type="button" data-pdf-preview>Önizle</button><button class="ka-btn ka-btn--secondary" type="button" data-pdf-download>İndir</button><button class="ka-btn ka-btn--secondary" type="button" data-pdf-share>Paylaş</button>${canEdit2()?'<button class="ka-btn" type="button" data-pdf-archive>Dokümanlara Kaydet</button>':''}</div></div></article>`;}
function metaFields(){const admin=active2().admin===true;return `<article class="ka-card"><div class="ka-card__body ka-stack"><label class="ka-field"><span class="ka-field__label">Belge Adı</span><input data-pdf-name value="${esc2(resultName.replace(/\.pdf$/i,''))}" placeholder="PDF Belgesi"></label><div class="ka-grid"><label class="ka-field"><span class="ka-field__label">Kategori</span><input data-pdf-category value="Diğer"></label>${admin?'<label class="ka-field"><span class="ka-field__label">Görünürlük</span><select data-pdf-visibility><option value="kisisel">Sadece Bana Özel</option><option value="herkes">Herkese Açık</option></select></label>':''}</div><label class="ka-field"><span class="ka-field__label">Açıklama</span><textarea data-pdf-description rows="2"></textarea></label></div></article>`;}
function imageCard(it,i){return `<article class="ka-card ka-list-card"><div class="ka-card__body ka-row"><img src="${esc2(it.url)}" alt="" style="width:64px;height:82px;object-fit:cover;border-radius:10px"><div class="ka-grow"><strong>${i+1}. ${esc2(it.ad)}</strong><div class="ka-muted">${esc2(it.filter)} · Parlaklık ${it.brightness} · Kontrast ${it.contrast}</div></div><div class="ka-row ka-wrap"><button class="ka-btn ka-btn--ghost ka-btn--sm" data-img-up="${i}">↑</button><button class="ka-btn ka-btn--ghost ka-btn--sm" data-img-down="${i}">↓</button><button class="ka-btn ka-btn--secondary ka-btn--sm" data-img-edit="${i}">Düzenle</button><button class="ka-btn ka-btn--danger ka-btn--sm" data-img-delete="${i}">Sil</button></div></div></article>`;}
function renderImages(){if(!mounted||kind!==PAGE_IMAGES)return;const r=root2();if(!r)return;setTitle2('Resimden PDF Oluştur');r.innerHTML=`<section class="ka-stack" data-pdf-images-page><div><h2>Resimden PDF Oluştur</h2><p class="ka-muted">Resimleri sırala, kırp, döndür ve belge filtresi uygulayarak tek PDF oluştur.</p></div><article class="ka-card"><div class="ka-card__body ka-stack"><label class="ka-field"><span class="ka-field__label">Resimler</span><input type="file" accept="image/*" multiple data-pdf-images></label><label class="ka-field"><span class="ka-field__label">Sayfa Yönü</span><select data-pdf-orientation><option value="otomatik" ${orientation==='otomatik'?'selected':''}>Otomatik</option><option value="dikey" ${orientation==='dikey'?'selected':''}>Dikey</option><option value="yatay" ${orientation==='yatay'?'selected':''}>Yatay</option></select></label><div class="ka-row ka-row--between"><span class="ka-badge">${images.length} resim</span><button class="ka-btn" type="button" data-pdf-create ${images.length?'':'disabled'}>PDF Oluştur</button></div></div></article><div class="ka-stack">${images.length?images.map(imageCard).join(''):'<div class="ka-empty">Henüz resim seçilmedi.</div>'}</div>${resultControls()}${metaFields()}</section>`;bindImages();}
function renderMerge(){if(!mounted||kind!==PAGE_MERGE)return;const r=root2();if(!r)return;setTitle2('PDF Birleştir');r.innerHTML=`<section class="ka-stack" data-pdf-merge-page><div><h2>PDF Birleştir</h2><p class="ka-muted">PDF sayfaları rasterize edilmeden birleştirilir; metin ve vektör içeriği korunur.</p></div><article class="ka-card"><div class="ka-card__body ka-stack"><label class="ka-field"><span class="ka-field__label">PDF Dosyaları</span><input type="file" accept="application/pdf,.pdf" multiple data-pdf-files></label><div class="ka-row ka-row--between"><span class="ka-badge">${pdfFiles.length} PDF</span><button class="ka-btn" type="button" data-pdf-merge ${pdfFiles.length?'':'disabled'}>Birleştir</button></div></div></article><div class="ka-stack">${pdfFiles.length?pdfFiles.map((f,i)=>`<article class="ka-card ka-list-card"><div class="ka-card__body ka-row"><div class="ka-grow"><strong>${i+1}. ${esc2(f.name)}</strong><div class="ka-muted">${bytes(f.size)}</div></div><button class="ka-btn ka-btn--ghost ka-btn--sm" data-file-up="${i}">↑</button><button class="ka-btn ka-btn--ghost ka-btn--sm" data-file-down="${i}">↓</button><button class="ka-btn ka-btn--danger ka-btn--sm" data-file-delete="${i}">Sil</button></div></article>`).join(''):'<div class="ka-empty">En az bir PDF seçin. Dosya sırası birleştirme sırasıdır.</div>'}</div>${resultControls()}${metaFields()}</section>`;bindMerge();}
function bindResult(){const r=root2();$('[data-pdf-name]',r)?.addEventListener('input',e=>{resultName=cleanPdfName(e.target.value,kind===PAGE_MERGE?'Birlesik_PDF':'Taranan_Belge')});$('[data-pdf-preview]',r)?.addEventListener('click',preview);$('[data-pdf-download]',r)?.addEventListener('click',()=>exportBlob(false));$('[data-pdf-share]',r)?.addEventListener('click',()=>exportBlob(true));$('[data-pdf-archive]',r)?.addEventListener('click',archive);}
function bindImages(){const r=root2();$('[data-pdf-images]',r)?.addEventListener('change',async e=>{const fs=[...e.target.files];revokeResult();cleanupImages();for(const f of fs)images.push(await normalizeSelectedImage(f));resultName=images.length>1?`${images.length} Sayfalik Belge.pdf`:(images[0]?.ad||'Taranan Belge').replace(/\.[^.]+$/,'.pdf');renderImages();if(images.length)openEditor(0)});$('[data-pdf-orientation]',r)?.addEventListener('change',e=>{orientation=e.target.value});$$('[data-img-up]',r).forEach(b=>b.onclick=()=>{move(images,+b.dataset.imgUp,-1);renderImages()});$$('[data-img-down]',r).forEach(b=>b.onclick=()=>{move(images,+b.dataset.imgDown,1);renderImages()});$$('[data-img-delete]',r).forEach(b=>b.onclick=()=>{const i=+b.dataset.imgDelete;if(images[i]?.url?.startsWith('blob:'))URL.revokeObjectURL(images[i].url);images.splice(i,1);revokeResult();renderImages()});$$('[data-img-edit]',r).forEach(b=>b.onclick=()=>openEditor(+b.dataset.imgEdit));$('[data-pdf-create]',r)?.addEventListener('click',createImagePdf);bindResult();}
function bindMerge(){const r=root2();$('[data-pdf-files]',r)?.addEventListener('change',e=>{pdfFiles=[...e.target.files];revokeResult();resultName=pdfFiles.length===1?`${pdfFiles[0].name.replace(/\.pdf$/i,'')} Birleştirilmiş.pdf`:`${pdfFiles.length} PDF Birleştirilmiş.pdf`;renderMerge()});$$('[data-file-up]',r).forEach(b=>b.onclick=()=>{move(pdfFiles,+b.dataset.fileUp,-1);renderMerge()});$$('[data-file-down]',r).forEach(b=>b.onclick=()=>{move(pdfFiles,+b.dataset.fileDown,1);renderMerge()});$$('[data-file-delete]',r).forEach(b=>b.onclick=()=>{pdfFiles.splice(+b.dataset.fileDelete,1);revokeResult();renderMerge()});$('[data-pdf-merge]',r)?.addEventListener('click',mergePdfs);bindResult();}
