async function mergePdfs(){if(!pdfFiles.length)return;const btn=$('[data-pdf-merge]');if(btn){btn.disabled=true;btn.textContent='Birleştiriliyor…'}try{await pdfLibReady();const {PDFDocument}=global.PDFLib,out=await PDFDocument.create();let count=0;for(let i=0;i<pdfFiles.length;i++){const f=pdfFiles[i];if(btn)btn.textContent=`${i+1}/${pdfFiles.length} · ${f.name}`;let src;try{src=await PDFDocument.load(new Uint8Array(await f.arrayBuffer()),{ignoreEncryption:false,updateMetadata:false})}catch(e){if(/encrypt|password/i.test(String(e?.message||'')))throw new Error(`“${f.name}” şifreli; şifreli PDF birleştirilemez.`);throw new Error(`“${f.name}” açılamadı: ${e.message}`)}const idx=src.getPageIndices(),pages=await out.copyPages(src,idx);pages.forEach(p=>out.addPage(p));count+=pages.length;await new Promise(r=>setTimeout(r,0))}if(!count)throw new Error('Birleştirilecek sayfa bulunamadı.');const data=await out.save({useObjectStreams:true,addDefaultPage:false,objectsPerTick:30});revokeResult();resultBlob=new Blob([data],{type:'application/pdf'});resultName=cleanPdfName($('[data-pdf-name]')?.value||resultName,'Birlesik PDF');notify(`${count} sayfa birleştirildi. Metin ve vektör içeriği korundu.`);renderMerge()}catch(e){console.error('[DocumentsPdfTools/merge]',e);notify('PDF birleştirme hatası: '+e.message)}finally{if(btn){btn.disabled=false;btn.textContent='Birleştir'}}}
async function preview(){if(!resultBlob)return;revokePreviewOnly();resultUrl=URL.createObjectURL(resultBlob);try{const viewer=await global.DocumentsModule?.ensureViewer?.();if(viewer?.ac)await viewer.ac(resultUrl,cleanPdfName(resultName));else global.open(resultUrl,'_blank')}catch(e){global.open(resultUrl,'_blank')}}
function blobBase64(blob){return new Promise((ok,no)=>{const r=new FileReader();r.onloadend=()=>ok(String(r.result).split(',')[1]||'');r.onerror=no;r.readAsDataURL(blob)});}
