function editorHtml(it,i){const d=it.details||defaultDetails(),range=(k,l,min,max,val)=>`<label class="ka-field"><span class="ka-field__label">${l}: <b data-val-${k}>${val}</b></span><input type="range" min="${min}" max="${max}" value="${val}" data-editor-range="${k}"></label>`;return `<div class="ka-modal-backdrop" data-pdf-editor style="z-index:1400"><section class="ka-modal" style="width:min(960px,calc(100vw - 16px));max-height:94dvh"><header class="ka-modal__header"><div><h3>Resim Düzenle</h3><p class="ka-muted">${i+1}/${images.length} · ${esc2(it.ad)}</p></div><button class="ka-icon-button" type="button" data-editor-close>×</button></header><div class="ka-modal__body ka-stack"><div data-editor-stage style="position:relative;max-width:100%;background:#111;overflow:hidden;touch-action:none"><img data-editor-img src="${esc2(it.url)}" alt="" style="display:block;max-width:100%;max-height:48dvh;margin:auto;user-select:none"><svg data-editor-svg style="position:absolute;inset:0;width:100%;height:100%;overflow:visible;pointer-events:none"><polygon data-crop-poly fill="rgba(16,185,129,.12)" stroke="white" stroke-width="2"></polygon>${['tl','tr','br','bl'].map(k=>`<circle data-crop-handle="${k}" r="12" fill="#ff9800" stroke="white" stroke-width="2" style="pointer-events:auto;touch-action:none"></circle>`).join('')}</svg></div><div class="ka-row ka-wrap"><button class="ka-btn ka-btn--secondary" type="button" data-editor-rotate>↻ Döndür</button><button class="ka-btn ka-btn--secondary" type="button" data-editor-auto>🔍 Otomatik Algıla</button><button class="ka-btn ka-btn--secondary" type="button" data-editor-crop>✂️ Kırp</button><button class="ka-btn ka-btn--secondary" type="button" data-editor-reset>Köşeleri Sıfırla</button>${['orijinal','belge','gri','bw'].map(f=>`<button class="ka-btn ${it.filter===f?'':'ka-btn--secondary'}" type="button" data-editor-filter="${f}">${f==='orijinal'?'Orijinal':f==='belge'?'Belge Modu':f==='gri'?'Gri Tonlama':'Siyah-Beyaz Metin'}</button>`).join('')}</div><div class="ka-grid">${range('brightness','Parlaklık',-50,50,it.brightness)}${range('contrast','Kontrast',-50,50,it.contrast)}${range('golge','Gölge Giderme',0,100,d.golge)}${range('sicaklik','Sıcaklık',-50,50,d.sicaklik)}${range('beyazlik','Beyazlık',0,100,d.beyazlik)}${range('metin','Metin Netliği',0,100,d.metin)}${range('netlik','Netlik',0,100,d.netlik)}${range('hareli','Hareli (Moiré) Giderme',0,100,d.hareli)}${range('gurultu','Gürültü Giderme',0,100,d.gurultu)}</div></div><footer class="ka-modal__footer"><button class="ka-btn" type="button" data-editor-done>Tamam</button></footer></section></div>`;}
function openEditor(i){if(!images[i])return;editorIndex=i;document.querySelector('[data-pdf-editor]')?.remove();document.body.insertAdjacentHTML('beforeend',editorHtml(images[i],i));const ov=$('[data-pdf-editor]'),img=$('[data-editor-img]',ov);const draw=()=>{const stage=$('[data-editor-stage]',ov),svg=$('[data-editor-svg]',ov),poly=$('[data-crop-poly]',ov);if(!stage||!svg||!img.complete)return;const sr=stage.getBoundingClientRect(),ir=img.getBoundingClientRect(),left=ir.left-sr.left,top=ir.top-sr.top,w=ir.width,h=ir.height,c=images[i].corners;svg.setAttribute('viewBox',`0 0 ${sr.width} ${sr.height}`);const pts=['tl','tr','br','bl'].map(k=>`${left+c[k].x*w},${top+c[k].y*h}`).join(' ');poly.setAttribute('points',pts);for(const k of ['tl','tr','br','bl']){const hnd=$(`[data-crop-handle="${k}"]`,ov);hnd.setAttribute('cx',left+c[k].x*w);hnd.setAttribute('cy',top+c[k].y*h)}};img.onload=draw;requestAnimationFrame(draw);global.addEventListener('resize',draw,{once:true});for(const hnd of $$('[data-crop-handle]',ov)){hnd.addEventListener('pointerdown',e=>{e.preventDefault();hnd.setPointerCapture?.(e.pointerId);const k=hnd.dataset.cropHandle,stage=$('[data-editor-stage]',ov);const move2=ev=>{const ir=img.getBoundingClientRect(),x=Math.max(0,Math.min(1,(ev.clientX-ir.left)/ir.width)),y=Math.max(0,Math.min(1,(ev.clientY-ir.top)/ir.height));images[i].corners[k]={x,y};draw()};const up=()=>{hnd.removeEventListener('pointermove',move2);hnd.removeEventListener('pointerup',up)};hnd.addEventListener('pointermove',move2);hnd.addEventListener('pointerup',up)})}$$('[data-editor-filter]',ov).forEach(b=>b.onclick=()=>{images[i].filter=b.dataset.editorFilter;openEditor(i)});$$('[data-editor-range]',ov).forEach(sl=>sl.oninput=()=>{const k=sl.dataset.editorRange,v=Number(sl.value),it=images[i];if(k==='brightness')it.brightness=v;else if(k==='contrast')it.contrast=v;else{it.details=it.details||defaultDetails();it.details[k]=v}const lbl=$(`[data-val-${k}]`,ov);if(lbl)lbl.textContent=v});$('[data-editor-rotate]',ov).onclick=async()=>{ov.remove();await rotate(i);openEditor(i)};$('[data-editor-auto]',ov).onclick=async()=>{const found=autoCorners(await imgLoad(images[i].url));if(found){images[i].corners=found;draw();notify('Köşeler otomatik bulundu.')}else notify('Köşeler otomatik bulunamadı; elle ayarlayın.')};$('[data-editor-crop]',ov).onclick=async()=>{try{const it=images[i],img2=await imgLoad(it.url),c=perspectiveCanvas(img2,it.corners||defaultCorners()),url=c.toDataURL('image/jpeg',.95);if(it.url?.startsWith('blob:'))URL.revokeObjectURL(it.url);it.url=url;it.corners=defaultCorners();ov.remove();revokeResult();renderImages();openEditor(i);notify('Kırpıldı.')}catch(e){notify('Kırpma hatası: '+e.message)}};$('[data-editor-reset]',ov).onclick=()=>{images[i].corners=defaultCorners();draw()};const close=()=>{ov.remove();editorIndex=-1;revokeResult();renderImages()};$('[data-editor-close]',ov).onclick=close;$('[data-editor-done]',ov).onclick=close;ov.onclick=e=>{if(e.target===ov)close()};}
async function open(page){if(!canView2())return notify('Bu aracı görüntüleme yetkiniz yok.');cleanup();kind=page===PAGE_MERGE?PAGE_MERGE:PAGE_IMAGES;await global.ShellUI?.routeModule?.('documents',{bottom:'menu',title:kind===PAGE_MERGE?'PDF Birleştir':'Resimden PDF Oluştur'});global.DocumentsModule?.unmount?.();mounted=true;resultName=kind===PAGE_MERGE?'Birlesik PDF.pdf':'Taranan Belge.pdf';kind===PAGE_MERGE?renderMerge():renderImages();return true;}
